// Manual ZIP parsing - docx files are ZIP archives
const fs = require('fs');
const buf = fs.readFileSync('/workspace/testbed/docs/customer_report.docx');

// Find 'word/document.xml' in the zip
// Look for local file headers (PK\x03\x04)
const entries = [];
let offset = 0;
while (offset < buf.length - 4) {
  if (buf[offset] === 0x50 && buf[offset+1] === 0x4b && buf[offset+2] === 0x03 && buf[offset+3] === 0x04) {
    const nameLen = buf.readUInt16LE(offset + 26);
    const extraLen = buf.readUInt16LE(offset + 28);
    const compMethod = buf.readUInt16LE(offset + 8);
    const compSize = buf.readUInt32LE(offset + 18);
    const uncompSize = buf.readUInt32LE(offset + 22);
    const name = buf.slice(offset + 30, offset + 30 + nameLen).toString('utf8');
    const dataOffset = offset + 30 + nameLen + extraLen;
    entries.push({ name, compMethod, compSize, uncompSize, dataOffset });
    offset = dataOffset + compSize;
  } else {
    offset++;
  }
}

const entry = entries.find(e => e.name === 'word/document.xml');
if (!entry) { console.log('Entries:', entries.map(e=>e.name)); process.exit(1); }

let data;
if (entry.compMethod === 0) {
  data = buf.slice(entry.dataOffset, entry.dataOffset + entry.uncompSize);
} else {
  const zlib = require('zlib');
  const compressed = buf.slice(entry.dataOffset, entry.dataOffset + entry.compSize);
  data = zlib.inflateRawSync(compressed);
}

let xml = data.toString('utf8');
// Extract text: split on paragraph tags, strip XML tags
let text = xml
  .replace(/<w:p[ >]/g, '\n<w:p ')
  .replace(/<[^>]+>/g, '')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '\"')
  .replace(/&apos;/g, \"'\")
  .trim();
console.log(text);
